import { NextResponse } from "next/server";
import puppeteer from "puppeteer";
import ejs from "ejs";
import path from "path";

export async function POST(req: Request) {
  try {
    const body = await req.json();
    const records = body?.payload || [];

    const chunkSize = 5000; 
    const totalChunks = Math.ceil(records.length / chunkSize);

    const templatePath = path.resolve(
      process.cwd(),
      "src/views/report.ejs"
    );

    let fullHTML = "";

    for (let i = 0; i < totalChunks; i++) {
      const chunk = records.slice(i * chunkSize, (i + 1) * chunkSize);

      const chunkHTML = await ejs.renderFile(templatePath, {
        payload: chunk,
      });
      fullHTML += chunkHTML;
    }

    const browser = await puppeteer.launch({
      headless: true,
      args: ["--no-sandbox", "--disable-setuid-sandbox"],
    });

    const page = await browser.newPage();
    await page.setContent(fullHTML, { waitUntil: "networkidle0" });

    const pdfBuffer = await page.pdf({
      format: "A4",
      printBackground: true,
      margin: { top: "10mm", left: "10mm", bottom: "10mm", right: "10mm" },
    });

    await page.close();
    await browser.close();

    return new NextResponse(Buffer.from(pdfBuffer), {
      status: 200,
      headers: {
        "Content-Type": "application/pdf",
        "Content-Disposition": "attachment; filename=report.pdf",
      },
    });

  } catch (error) {
    console.error("PDF Error:", error);
    return NextResponse.json({ error: "Failed to generate PDF" }, { status: 500 });
  }
}
